/* Transparency & Compliance (Track 7, phase 34). Extends the existing Trust & Safety engine (services/safety.js:
 * reports, decisions, appeals; ctx.audit chain) instead of duplicating it:
 * 1. Periodic transparency report — aggregate counts per month/quarter, generated by a leased ctx.scheduler job,
 *    stored in transparency_reports, public at /api/transparency and as a readable page at /transparency.
 * 2. Report status for the reporter — timeline per report (/api/me/reports) and a notification when it is decided
 *    (report_updates is the once-per-status ledger; CONTENT_REMOVED triggers it at once, a 2-minute sync catches dismissals).
 * 3. Data-subject requests — export (JSON or ZIP), account deletion with a grace period then anonymisation (cancellable),
 *    and free-text requests (correction / objection / question) with the PDPL 30-day deadline.
 * 4. Retention — per-type rules (lib/compliance-lib.js RETENTION) with admin overrides; DRY-RUN unless RETENTION_ENFORCE=1;
 *    media blobs are only ever deleted with RETENTION_MEDIA_BLOBS=1 (retention) / COMPLIANCE_DELETE_MEDIA_BLOBS=1 (erasure).
 * 5. PDPL support — consent history, purposes + processing register, breach log (72-hour clock), rights endpoints.
 * 6–7. Plain-language Terms / Privacy / Retention documents (lib/compliance-policies.js) at /api/legal and /legal/*.
 * 8. Account decision log — platform decisions + community moderation + account status, with reasons and appeal links.
 * Engineering support for compliance, not legal advice (docs/COMPLIANCE.md). */
const { E, str, oneOf, id, now, verifyPassword } = require("../lib/core");
const { SEC_HEADERS } = require("../lib/http");
const L = require("../lib/compliance-lib");
const P = require("../lib/compliance-policies");
const { log } = require("../lib/log");

module.exports = (ctx) => {
  const { db, bus } = ctx;
  const R = ctx.router, A = ctx.requireUser;
  const isAdmin = (u) => u && u.role === "admin";
  const admin = (fn) => A(async (req, res) => { if (!isAdmin(req.user)) throw E.forbid("للإدارة فقط"); return fn(req, res); });
  const env = (k, d) => (process.env[k] === undefined || process.env[k] === "" ? d : process.env[k]);
  const minBucket = () => Math.max(0, +env("TRANSPARENCY_MIN_COUNT", 3) || 0);

  /* ---------- schema introspection (other phases add tables; every step tolerates their absence) ---------- */
  let tablesP = null; const colsC = new Map();
  const tables = () => (tablesP ||= (db.dialect === "postgres"
    ? db.all("SELECT table_name AS name FROM information_schema.tables WHERE table_schema = current_schema()")
    : db.all("SELECT name FROM sqlite_master WHERE type='table'")).then(r => new Set(r.map(x => x.name))).catch(e => { tablesP = null; throw e; }));
  async function columns(t) {
    if (colsC.has(t)) return colsC.get(t);
    const rows = db.dialect === "postgres" ? await db.all("SELECT column_name AS name FROM information_schema.columns WHERE table_schema = current_schema() AND table_name=$1", [t]) : await db.all(`PRAGMA table_info(${t})`);
    const s = new Set(rows.map(r => r.name)); colsC.set(t, s); return s;
  }
  const hasTable = async (t) => (await tables()).has(t);
  const SAFE = /^[a-z_][a-z0-9_]*$/;

  const notifyFn = () => ctx.services.notify?.notify || ctx.services.messaging?.notify;
  async function notifyUser(uid, kind, opts = {}) { try { const f = notifyFn(); if (f) await f(uid, kind, opts); } catch (e) { log.warn?.("compliance notify failed", { kind, err: e.message }); } }

  /* =====================================================================
   * 1. Transparency reports
   * ===================================================================== */
  async function buildTransparency(period) {
    const r = L.periodRange(period); if (!r) throw E.bad("صيغة الفترة: YYYY-MM أو YYYY-Qn");
    if (Date.parse(r.end) > Date.now()) throw E.bad("لا يُنشر تقرير لفترة لم تنتهِ بعد");
    const p = [r.start, r.end], min = minBucket(), T = await tables();
    const received = await db.all("SELECT kind FROM reports WHERE created_at >= $1 AND created_at < $2", p);
    const resolved = await db.all("SELECT status, created_at, resolved_at FROM reports WHERE resolved_at >= $1 AND resolved_at < $2 AND status<>'open'", p);
    const stillOpen = (await db.get("SELECT COUNT(*) n FROM reports WHERE created_at >= $1 AND created_at < $2 AND status='open'", p)).n;
    const decisions = await db.all("SELECT action, restored FROM decisions WHERE created_at >= $1 AND created_at < $2", p);
    const appealsIn = (await db.get("SELECT COUNT(*) n FROM appeals WHERE created_at >= $1 AND created_at < $2", p)).n;
    const appealsOut = await db.all("SELECT status, created_at, resolved_at FROM appeals WHERE resolved_at >= $1 AND resolved_at < $2 AND status<>'open'", p);
    const modRows = T.has("mod_actions") ? await db.all("SELECT action, actor FROM mod_actions WHERE created_at >= $1 AND created_at < $2 AND action IN ('remove','reject','warn','mute','ban','dismiss','automod_reject','automod_queue')", p) : [];
    const acct = await db.all("SELECT action FROM audit_log WHERE at >= $1 AND at < $2 AND action IN ('USER_SUSPENDED','USER_ACTIVE','ABUSE_FLAG','ACCOUNT_ANONYMISED')", p);
    const dsr = await db.all("SELECT kind, status FROM dsr_requests WHERE created_at >= $1 AND created_at < $2", p);
    const hours = (a, b) => (Date.parse(b) - Date.parse(a)) / 3600e3;
    const outcome = L.countBy(resolved, "status"), acc = L.countBy(acct, "action"), dk = L.countBy(dsr, "kind");
    const mh = L.median(resolved.map(x => hours(x.created_at, x.resolved_at)));
    const ma = L.median(appealsOut.map(x => hours(x.created_at, x.resolved_at)));
    const round = (x) => (x === null ? null : Math.round(x * 10) / 10);
    return {
      period, label: L.periodLabel(period), kind: r.kind, startsAt: r.start, endsAt: r.end, generatedAt: now(), minCount: min,
      reports: { received: received.length, byKind: L.suppress(L.countBy(received, "kind"), min), resolved: resolved.length, actioned: outcome.actioned || 0, dismissed: outcome.dismissed || 0, stillOpen: Number(stillOpen), medianHoursToDecision: round(mh) },
      decisions: { total: decisions.length, byAction: L.suppress(L.countBy(decisions, "action"), min), reversedOnAppeal: decisions.filter(d => +d.restored).length },
      appeals: { received: Number(appealsIn), decided: appealsOut.length, accepted: appealsOut.filter(a => a.status === "accepted").length, rejected: appealsOut.filter(a => a.status === "rejected").length, medianHoursToDecision: round(ma) },
      communityModeration: { total: modRows.length, byAction: L.suppress(L.countBy(modRows, "action"), min), automated: modRows.filter(m => m.actor === "system").length },
      accounts: { suspended: acc.USER_SUSPENDED || 0, reinstated: acc.USER_ACTIVE || 0, massActionFlags: acc.ABUSE_FLAG || 0, deletedOnRequest: acc.ACCOUNT_ANONYMISED || 0 },
      dataRequests: { export: dk.export || 0, delete: dk.delete || 0, other: dsr.length - (dk.export || 0) - (dk.delete || 0) },
      notes: ["الأرقام مجمّعة ولا تحتوي أي بيانات شخصية.", min > 1 ? `التصنيفات التي يقل عددها عن ${min} تظهر «<${min}» حتى لا تدل على أشخاص بعينهم؛ المجاميع دقيقة.` : null, "طلبات الجهات الحكومية لا يسجّلها النظام آلياً بعد، لذلك لا تظهر هنا."].filter(Boolean)
    };
  }
  async function generateTransparency(period, by = "system", { force = false } = {}) {
    const existing = await db.get("SELECT period FROM transparency_reports WHERE period=$1", [period]);
    if (existing && !force) return { period, skipped: true };
    const data = await buildTransparency(period), r = L.periodRange(period);
    await db.run(`INSERT INTO transparency_reports(period,kind,starts_at,ends_at,data,published,generated_by,generated_at) VALUES($1,$2,$3,$4,$5,1,$6,$7)
      ON CONFLICT (period) DO UPDATE SET data=$5, generated_by=$6, generated_at=$7`, [period, r.kind, r.start, r.end, data, by, data.generatedAt]);
    await ctx.audit("TRANSPARENCY_REPORT", period, existing ? "regenerated" : "generated", by);
    return { period, generated: true, data };
  }
  async function transparencyJob(date = new Date()) {
    const out = [];
    for (const k of ["month", "quarter"]) out.push(await generateTransparency(L.previousPeriod(k, date)));
    return out;
  }
  const headline = (row) => { const d = row.data || {}; return { period: row.period, kind: row.kind, label: d.label || L.periodLabel(row.period), startsAt: row.starts_at, endsAt: row.ends_at, generatedAt: row.generated_at, reports: d.reports?.received ?? 0, actioned: d.reports?.actioned ?? 0, appeals: d.appeals?.received ?? 0, reversed: d.decisions?.reversedOnAppeal ?? 0 }; };
  const listTransparency = async () => (await db.all("SELECT * FROM transparency_reports WHERE published=1 ORDER BY starts_at DESC, kind LIMIT 60")).map(headline);
  async function getTransparency(period) { const row = await db.get("SELECT * FROM transparency_reports WHERE period=$1 AND published=1", [period]); if (!row) throw E.nf("لا يوجد تقرير لهذه الفترة"); return row.data; }

  /* =====================================================================
   * 2. Report status for the reporter
   * ===================================================================== */
  async function recordUpdate(report, status, { notify = true } = {}) {
    const ins = await db.run("INSERT INTO report_updates(id,report_id,user_id,status,notified,at) VALUES($1,$2,$3,$4,0,$5) ON CONFLICT DO NOTHING", [id("ru"), report.id, report.by_user, status, now()]);
    if (!ins.changes) return false;
    if (notify) { await notifyUser(report.by_user, "report_update", { ref: report.id }); await db.run("UPDATE report_updates SET notified=1 WHERE report_id=$1 AND status=$2", [report.id, status]); }
    return true;
  }
  /** decided reports whose reporter has not been told yet; old decisions (before this phase shipped) are back-filled silently */
  async function syncReportUpdates({ limit = 500, backfillHours = +env("COMPLIANCE_REPORT_BACKFILL_HOURS", 72) } = {}) {
    const rows = await db.all(`SELECT r.id, r.by_user, r.status, r.resolved_at FROM reports r WHERE r.status<>'open' AND NOT EXISTS (SELECT 1 FROM report_updates u WHERE u.report_id=r.id AND u.status=r.status) ORDER BY r.resolved_at LIMIT ${Math.max(1, Math.min(5000, limit | 0))}`);
    let notified = 0, backfilled = 0; const edge = Date.now() - backfillHours * 3600e3;
    for (const r of rows) {
      const old = r.resolved_at && Date.parse(r.resolved_at) < edge;
      const real = r.by_user !== "anonymised" && (await db.get("SELECT status FROM users WHERE id=$1", [r.by_user]))?.status === "active";
      if (await recordUpdate(r, r.status, { notify: !old && real })) old || !real ? backfilled++ : notified++;
    }
    return { notified, backfilled };
  }
  let syncTimer = null;
  const syncSoon = () => { if (syncTimer) return; syncTimer = setTimeout(() => { syncTimer = null; syncReportUpdates().catch(e => log.warn?.("report sync failed", { err: e.message })); }, 50); syncTimer.unref?.(); };
  bus.on("REPORT_CREATED", async (e) => { const r = await db.get("SELECT id, by_user FROM reports WHERE id=$1", [e.report]); if (r) await recordUpdate(r, "open", { notify: false }); });
  bus.on("CONTENT_REMOVED", syncSoon);
  bus.on("REPORT_RESOLVED", syncSoon); // optional one-line emit in safety.js (INTEGRATION.md); the scheduled sync covers it otherwise

  async function reportView(r) {
    const restored = r.status === "actioned" && !!(await db.get("SELECT 1 x FROM decisions WHERE target=$1 AND restored=1", [r.target]));
    const p = r.kind === "post" ? await db.get("SELECT status, moderation FROM posts WHERE id=$1", [r.target]) : null;
    return {
      id: r.id, kind: r.kind, kindLabel: L.KIND_LABEL[r.kind] || "عنصر", reason: r.reason, status: r.status, statusLabel: L.REPORT_STATUS[r.status] || r.status,
      createdAt: r.created_at, resolvedAt: r.resolved_at || null, href: p && p.status === "published" ? `/#/post/${r.target}` : null,
      timeline: L.reportTimeline(r, { restored, hidden: !!p && p.moderation === "reported" })
    };
  }
  async function myReports(user) {
    const rows = await db.all("SELECT * FROM reports WHERE by_user=$1 ORDER BY created_at DESC LIMIT 200", [user.id]);
    const out = []; for (const r of rows) out.push(await reportView(r));
    return { reports: out, counts: { open: out.filter(r => r.status === "open").length, decided: out.filter(r => r.status !== "open").length } };
  }

  /* =====================================================================
   * 3. Data-subject requests: export, deletion, other requests
   * ===================================================================== */
  async function newRequest(uid, kind, { status = "received", detail = null, meta = null, scheduledFor = null } = {}) {
    const t = now(), rid = id("dsr");
    await db.run("INSERT INTO dsr_requests(id,user_id,kind,status,detail,meta,due_at,scheduled_for,created_at,updated_at) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9,$9)", [rid, uid, kind, status, detail, meta, L.dsrDue(t), scheduledFor, t]);
    return rid;
  }
  async function collect(uid) {
    const T = await tables(), sections = {}, counts = {};
    for (const m of L.DATA_MAP) {
      if (m.export === false || !T.has(m.t)) continue;
      const cols = await columns(m.t);
      const order = ["created_at", "at", "joined_at", "added_at", "first_seen", "updated_at"].find(c => cols.has(c));
      const rows = await db.all(`SELECT * FROM ${m.t} WHERE ${m.user}${order ? ` ORDER BY ${order}` : ""} LIMIT 100000`, [uid]).catch(e => { log.warn?.("export section failed", { t: m.t, err: e.message }); return null; });
      if (!rows) continue;
      sections[m.t] = m.t === "users" ? rows.map(r => L.cleanRow(r, null))[0] || null : rows.map(r => L.cleanRow(r, m.cols || null));
      counts[m.t] = m.t === "users" ? 1 : rows.length;
    }
    return { sections, counts };
  }
  async function exportData(req, res) {
    const u = req.user, format = oneOf(req.query.format, ["json", "zip"], "json");
    const cool = +env("COMPLIANCE_EXPORT_COOLDOWN_S", 300);
    if (cool > 0) { const last = await db.get("SELECT created_at FROM dsr_requests WHERE user_id=$1 AND kind='export' ORDER BY created_at DESC LIMIT 1", [u.id]); if (last && Date.now() - Date.parse(last.created_at) < cool * 1000) throw E.rate(); }
    const { sections, counts } = await collect(u.id);
    const meta = { exportedAt: now(), app: "mujtama-plus", version: ctx.config.version, format, user: u.id, handle: u.handle, counts,
      register: L.DATA_MAP.filter(m => counts[m.t] !== undefined).map(m => ({ table: m.t, category: m.category, purpose: L.PURPOSES[m.purpose]?.label, basis: L.BASIS_LABEL[L.PURPOSES[m.purpose]?.basis], retention: m.retention })) };
    const rid = await newRequest(u.id, "export", { status: "completed", meta: { format, counts } });
    await db.run("UPDATE dsr_requests SET completed_at=$1 WHERE id=$2", [now(), rid]);
    await ctx.audit("DATA_EXPORTED", u.id, format, u.id);
    const base = `mujtama-plus-${u.handle}-${meta.exportedAt.slice(0, 10)}`;
    let body, type;
    if (format === "json") { body = Buffer.from(JSON.stringify({ meta, ...sections }, null, 2)); type = "application/json; charset=utf-8"; }
    else {
      const files = [{ name: "README.txt", data: readme(meta) }, { name: "meta.json", data: JSON.stringify(meta, null, 2) }];
      for (const [t, rows] of Object.entries(sections)) files.push({ name: `data/${t}.json`, data: JSON.stringify(rows, null, 2) });
      const media = Array.isArray(sections.media) ? sections.media.filter(m => m.status !== "deleted" && m.status !== "purged") : [];
      const maxBytes = +env("COMPLIANCE_EXPORT_MEDIA_MAX_MB", 25) * 1048576; let total = 0; const skipped = [];
      for (const m of media) {
        if (total + (+m.size || 0) > maxBytes) { skipped.push(m.id); continue; }
        const buf = await ctx.storage.get(m.storage_key).catch(() => null);
        if (!buf) { skipped.push(m.id); continue; }
        total += buf.length; files.push({ name: `media/${String(m.storage_key).replace(/[^\w.-]/g, "_")}`, data: buf });
      }
      if (skipped.length) files.push({ name: "media/NOT_INCLUDED.txt", data: `لم تُضمَّن هذه الملفات بسبب حجمها أو تعذّر قراءتها، ويمكنك تنزيلها من التطبيق:\n${skipped.join("\n")}\n` });
      body = L.zip(files); type = "application/zip";
    }
    res.writeHead(200, { ...SEC_HEADERS, "Content-Type": type, "Content-Length": body.length, "Cache-Control": "no-store", "Content-Disposition": `attachment; filename="${base}.${format}"` });
    res.end(body);
    return ctx.STREAM;
  }
  function readme(meta) {
    return [`نسخة من بياناتك في مجتمع بلس — ${meta.exportedAt}`, "", "ماذا يوجد هنا:", "• meta.json: وصف النسخة وسجل المعالجة لكل نوع (الغرض، الأساس، مدة الاحتفاظ).", "• data/: ملف JSON لكل نوع من البيانات (يفتح بأي محرر نصوص).", "• media/: الصور والفيديو التي رفعتها (حتى حد الحجم).", "",
      "لم نضمّن: كلمات المرور ورموز التحقق ومفاتيح التشفير الخاصة (لا نملك نسخة مقروءة منها أصلاً)، ولا رسائل الآخرين إليك احتراماً لخصوصيتهم.", "", ...Object.entries(meta.counts).map(([t, n]) => `${t}: ${n}`), ""].join("\n");
  }

  async function scheduleDeletion(user, b = {}) {
    if (isAdmin(user)) throw E.forbid("حسابات الإدارة تُحذف بعد نقل الصلاحيات يدوياً");
    if (await db.get("SELECT 1 x FROM dsr_requests WHERE user_id=$1 AND kind='delete' AND status IN ('scheduled','processing')", [user.id])) throw E.conflict("طلب الحذف مسجّل مسبقاً");
    if (b.confirm !== "حذف") throw E.bad("اكتب كلمة «حذف» للتأكيد");
    if (user.password_hash) { const full = await db.get("SELECT password_hash FROM users WHERE id=$1", [user.id]); if (!verifyPassword(String(b.password || ""), full.password_hash)) throw E.forbid("كلمة المرور غير صحيحة"); }
    const grace = L.GRACE_DAYS(), when = new Date(Date.now() + grace * L.DAY).toISOString();
    const rid = await newRequest(user.id, "delete", { status: "scheduled", detail: str(b.reason, 500), scheduledFor: when, meta: { graceDays: grace } });
    await ctx.audit("DELETION_SCHEDULED", user.id, when, user.id);
    await notifyUser(user.id, "privacy_request", { ref: rid });
    if (grace === 0) await processDueDeletions();
    return { id: rid, scheduledFor: when, graceDays: grace };
  }
  async function cancelDeletion(user) {
    const r = await db.run("UPDATE dsr_requests SET status='cancelled', cancelled_at=$1, updated_at=$1 WHERE user_id=$2 AND kind='delete' AND status='scheduled'", [now(), user.id]);
    if (!r.changes) throw E.nf("لا يوجد طلب حذف قابل للإلغاء");
    await ctx.audit("DELETION_CANCELLED", user.id, null, user.id);
    return { ok: true };
  }
  async function processDueDeletions() {
    const due = await db.all("SELECT * FROM dsr_requests WHERE kind='delete' AND status='scheduled' AND scheduled_for <= $1 ORDER BY scheduled_for LIMIT 20", [now()]);
    const done = [];
    for (const d of due) {
      const claim = await db.run("UPDATE dsr_requests SET status='processing', updated_at=$1 WHERE id=$2 AND status='scheduled'", [now(), d.id]);
      if (!claim.changes) continue;
      try {
        const steps = await eraseUser(d.user_id);
        await db.run("UPDATE dsr_requests SET status='completed', completed_at=$1, updated_at=$1, meta=$2 WHERE id=$3", [now(), { ...(d.meta || {}), steps }, d.id]);
        done.push(d.user_id);
      } catch (e) {
        log.error("account erasure failed", { dsr: d.id, err: e.message });
        await db.run("UPDATE dsr_requests SET status='scheduled', updated_at=$1, meta=$2 WHERE id=$3", [now(), { ...(d.meta || {}), lastError: e.message }, d.id]);
      }
    }
    return done;
  }
  /** irreversible: personal data removed, content text scrubbed, the users row kept as «مستخدم محذوف» so references stay valid */
  async function eraseUser(uid) {
    const T = await tables(), steps = {}, t = now();
    const u = await db.get("SELECT * FROM users WHERE id=$1", [uid]); if (!u) throw new Error("user not found");
    const run = async (label, sql, p = [uid]) => { try { steps[label] = (await db.run(sql, p)).changes; } catch (e) { steps[label] = "error: " + e.message; log.warn?.("erase step failed", { label, err: e.message }); } };
    // 1) media blobs (opt-in) before the media rows lose their keys
    if (T.has("media")) {
      if (env("COMPLIANCE_DELETE_MEDIA_BLOBS", "0") === "1") { let n = 0; for (const m of await db.all("SELECT storage_key FROM media WHERE owner=$1", [uid])) { try { await ctx.storage.del(m.storage_key); n++; } catch { } } steps.media_blobs = n; }
      else steps.media_blobs = "kept (COMPLIANCE_DELETE_MEDIA_BLOBS≠1)";
      await run("media", "UPDATE media SET status='deleted' WHERE owner=$1");
    }
    // 2) content: scrub text, keep ids so threads and counts stay consistent
    if (T.has("post_versions")) await run("post_versions", "DELETE FROM post_versions WHERE post_id IN (SELECT id FROM posts WHERE author=$1)");
    if (T.has("post_hashtags")) await run("post_hashtags", "DELETE FROM post_hashtags WHERE post_id IN (SELECT id FROM posts WHERE author=$1)");
    if (T.has("search_docs")) await run("search_docs", "DELETE FROM search_docs WHERE author=$1");
    const pc = await columns("posts");
    await run("posts", `UPDATE posts SET status='deleted', text='', title=NULL, data=NULL, location=NULL${pc.has("updated_at") ? ", updated_at=$2" : ""} WHERE author=$1`, pc.has("updated_at") ? [uid, t] : [uid]);
    await run("comments", "UPDATE comments SET status='deleted', text='' WHERE author=$1");
    if (T.has("messages")) { const mc = await columns("messages"); await run("messages", `UPDATE messages SET text=''${mc.has("payload") ? ", payload=NULL" : ""}${mc.has("meta") ? ", meta=NULL" : ""}${mc.has("deleted_at") ? ", deleted_at=$2" : ""} WHERE sender=$1`, mc.has("deleted_at") ? [uid, t] : [uid]); }
    // 3) rows that only describe the person: delete (owned communities keep their owner membership so they stay manageable)
    for (const m of L.DATA_MAP) {
      if (m.erase !== "delete" || !T.has(m.t) || m.t === "post_versions") continue;
      if (m.t === "memberships") { await run("memberships", "DELETE FROM memberships WHERE user_id=$1 AND role<>'owner'"); continue; }
      await run(m.t, `DELETE FROM ${m.t} WHERE ${m.user}`);
    }
    for (const extra of ["sessions", "push_subscriptions", "email_tokens", "webauthn_challenges"]) if (T.has(extra) && steps[extra] === undefined) await run(extra, `DELETE FROM ${extra} WHERE user_id=$1`);
    // 4) the account itself
    const uc = await columns("users"), /** @type {Array<[string, any]>} */ set = [["name", L.DELETED_NAME], ["handle", L.anonHandle(id("x").slice(2))], ["status", "deleted"], ["bio", ""], ["prefs", "{}"]];
    for (const c of ["password_hash", "pi_uid", "email", "email_verified_at", "avatar", "cover", "avatar_hash", "location", "country", "links", "expertise", "pinned", "pinned_posts", "sections", "badge", "verified", "privacy"]) if (uc.has(c)) set.push([c, null]);
    if (uc.has("private")) set.push(["private", 0]);
    const cols = set.filter(([c]) => uc.has(c) && SAFE.test(c));
    await run("users", `UPDATE users SET ${cols.map(([c], i) => `${c}=$${i + 2}`).join(", ")} WHERE id=$1`, [uid, ...cols.map(([, v]) => v)]);
    await ctx.audit("ACCOUNT_ANONYMISED", uid, "data-subject request", "system");
    ctx.cache.del("feed:"); ctx.cache.del("u:");
    bus.emit("USER_ANONYMISED", { user: uid });
    return steps;
  }

  const REQUEST_KINDS = { inquiry: "سؤال عن بياناتي", rectify: "تصحيح بيانات", object: "اعتراض على معالجة", restrict: "تقييد معالجة" };
  async function fileRequest(user, b = {}) {
    const kind = oneOf(b.kind, Object.keys(REQUEST_KINDS), null); if (!kind) throw E.bad("نوع الطلب غير معروف");
    const open = (await db.get("SELECT COUNT(*) n FROM dsr_requests WHERE user_id=$1 AND status IN ('received','extended')", [user.id])).n;
    if (open >= 5) throw E.conflict("لديك طلبات مفتوحة كثيرة؛ سنرد عليها أولاً");
    const rid = await newRequest(user.id, kind, { detail: str(b.text, 2000, { required: true, min: 5 }) });
    await ctx.audit("DSR_RECEIVED", rid, kind, user.id);
    return { id: rid, due: L.dsrDue(now()) };
  }
  async function answerRequest(adminUser, rid, b = {}) {
    const d = await db.get("SELECT * FROM dsr_requests WHERE id=$1", [rid]); if (!d) throw E.nf();
    if (!["received", "extended"].includes(d.status)) throw E.conflict("الطلب مغلق");
    const status = oneOf(b.status, ["completed", "rejected", "extended"], null); if (!status) throw E.bad();
    const response = str(b.response, 2000, { required: true, min: 3 });
    if (status === "extended") {
      if (d.meta?.extended) throw E.conflict("مُدّد مرة من قبل");
      await db.run("UPDATE dsr_requests SET status='extended', due_at=$1, response=$2, meta=$3, handled_by=$4, updated_at=$5 WHERE id=$6", [new Date(Date.parse(d.due_at) + L.DSR_DAYS * L.DAY).toISOString(), response, { ...(d.meta || {}), extended: true }, adminUser.id, now(), rid]);
    } else await db.run("UPDATE dsr_requests SET status=$1, response=$2, handled_by=$3, completed_at=$4, updated_at=$4 WHERE id=$5", [status, response, adminUser.id, now(), rid]);
    await ctx.audit("DSR_" + status.toUpperCase(), rid, null, adminUser.id);
    await notifyUser(d.user_id, "privacy_request", { ref: rid });
    return { ok: true };
  }
  const reqView = (r) => ({ id: r.id, kind: r.kind, kindLabel: REQUEST_KINDS[r.kind] || (r.kind === "export" ? "نسخة من بياناتي" : r.kind === "delete" ? "حذف الحساب" : r.kind), status: r.status, detail: r.detail, response: r.response, dueAt: r.due_at, scheduledFor: r.scheduled_for, completedAt: r.completed_at, cancelledAt: r.cancelled_at, createdAt: r.created_at });

  /* =====================================================================
   * 5. Consents, purposes, register, breach log
   * ===================================================================== */
  const consentCache = new Map();
  async function consents(uid) { return L.consentState(await db.all("SELECT id, purpose, granted, version, at FROM consents WHERE user_id=$1 ORDER BY id", [uid])); }
  /** for other services: may we process this user's data for `purpose`? (required purposes are always true) */
  async function hasConsent(uid, purpose) {
    if (!uid || !L.PURPOSES[purpose]) return true;
    const k = uid + ":" + purpose, c = consentCache.get(k); if (c && c.exp > Date.now()) return c.v;
    const v = (await consents(uid))[purpose].granted; consentCache.set(k, { v, exp: Date.now() + 60e3 }); if (consentCache.size > 20000) consentCache.clear();
    return v;
  }
  /* analytics consent is honoured for every user-attributed usage event: services call ctx.track(...) at call time,
   * so wrapping it here covers them all without touching their files (anonymous events pass through unchanged) */
  if (typeof ctx.track === "function" && !ctx.track.__consent) {
    const inner = ctx.track;
    const wrapped = (uid, name, props) => { if (!uid) return inner(uid, name, props); hasConsent(uid, "analytics").then(ok => { if (ok) inner(uid, name, props); }).catch(() => { }); };
    wrapped.__consent = true; ctx.track = wrapped;
  }
  async function setConsents(user, b = {}) {
    const cur = await consents(user.id), t = now(), changed = [];
    for (const [k, v] of Object.entries(b.purposes || {})) {
      const P0 = L.PURPOSES[k]; if (!P0 || P0.required || typeof v !== "boolean") continue;
      if (cur[k].explicit && cur[k].granted === v) continue;
      await db.run("INSERT INTO consents(user_id,purpose,granted,version,source,at) VALUES($1,$2,$3,$4,$5,$6)", [user.id, k, v ? 1 : 0, L.CONSENT_VERSION, oneOf(b.source, ["settings", "signup", "banner"], "settings"), t]);
      changed.push(k); consentCache.delete(user.id + ":" + k);
      if (k === "marketing_email" && !v && await hasTable("digest_settings")) await db.run("UPDATE digest_settings SET weekly_email=0, updated_at=$2 WHERE user_id=$1", [user.id, t]).catch(() => { });
    }
    if (b.acceptTerms) {
      const doc = P.documents().find(d => d.slug === "terms");
      await db.run("INSERT INTO consents(user_id,purpose,granted,version,source,at) VALUES($1,'terms',1,$2,$3,$4)", [user.id, doc.version, "settings", t]); changed.push("terms");
    }
    if (changed.length) await ctx.audit("CONSENT_CHANGED", user.id, changed.join(","), user.id);
    return { consents: await consents(user.id), changed };
  }
  function register() {
    const d = P.deployment();
    return {
      controller: d.controller, contact: d.contact, dpo: d.dpo, hostingRegion: d.hosting, version: L.CONSENT_VERSION,
      purposes: Object.entries(L.PURPOSES).map(([k, x]) => ({ key: k, label: x.label, basis: x.basis, basisLabel: L.BASIS_LABEL[x.basis], required: !!x.required, descr: x.descr })),
      activities: [...L.DATA_MAP.map(m => ({ table: m.t, category: m.category, purpose: m.purpose, purposeLabel: L.PURPOSES[m.purpose]?.label, retention: m.retention, onErasure: { delete: "تُحذف", scrub: "يُمسح المحتوى", keep: "يبقى بمعرّف لا يدل عليك", anon: "تُمحى البيانات الشخصية" }[m.erase] })),
        ...L.SYSTEM_RECORDS.map(m => ({ table: m.t, category: m.category, purpose: m.purpose, purposeLabel: L.PURPOSES[m.purpose]?.label, retention: m.retention, onErasure: "سجل نظامي" }))],
      recipients: ["مزوّد الاستضافة وقاعدة البيانات", "مزوّد البريد الإلكتروني (إن فُعّل SMTP_URL)", "خدمات الإشعارات الفورية في المتصفح (Web Push)", "Pi Network (عند استخدام Pi فقط)"],
      rights: { deadlineDays: L.DSR_DAYS, endpoints: ["GET /api/me/privacy", "GET /api/me/privacy/export?format=json|zip", "POST /api/me/privacy/deletion", "DELETE /api/me/privacy/deletion", "GET|PUT /api/me/consents", "POST /api/me/privacy/requests"] },
      disclaimer: "دعم هندسي للامتثال وليس استشارة قانونية."
    };
  }

  const SEVERITY = ["low", "medium", "high", "critical"], BSTATUS = ["open", "contained", "closed"];
  const isoOr = (v, d = null) => { if (v === undefined || v === null || v === "") return d; const t = Date.parse(v); if (!Number.isFinite(t)) throw E.bad("تاريخ غير صالح"); return new Date(t).toISOString(); };
  const breachView = (b) => {
    const due = L.breachDue(b.detected_at);
    return { id: b.id, title: b.title, description: b.description, severity: b.severity, status: b.status, occurredAt: b.occurred_at, detectedAt: b.detected_at, containedAt: b.contained_at, authorityNotifiedAt: b.authority_notified_at, usersNotifiedAt: b.users_notified_at,
      affectedCount: b.affected_count, categories: b.data?.categories || [], measures: b.data?.measures || null, notes: b.data?.notes || [], authorityDueAt: due,
      authorityDeadline: b.severity === "low" ? "n/a" : L.deadlineState(due, b.authority_notified_at, L.BREACH_HOURS * 3600e3), createdBy: b.created_by, createdAt: b.created_at, updatedAt: b.updated_at };
  };
  async function createBreach(user, b = {}) {
    const t = now(), bid = id("br");
    await db.run("INSERT INTO breach_log(id,title,description,severity,status,occurred_at,detected_at,affected_count,data,created_by,created_at,updated_at) VALUES($1,$2,$3,$4,'open',$5,$6,$7,$8,$9,$10,$10)",
      [bid, str(b.title, 200, { required: true, min: 3 }), str(b.description, 5000), oneOf(b.severity, SEVERITY, "medium"), isoOr(b.occurredAt), isoOr(b.detectedAt, t), Number.isFinite(+b.affectedCount) && b.affectedCount !== null && b.affectedCount !== "" ? Math.max(0, Math.round(+b.affectedCount)) : null,
        { categories: (Array.isArray(b.categories) ? b.categories : []).map(c => String(c).slice(0, 60)).slice(0, 30), measures: str(b.measures, 5000), notes: [] }, user.id, t]);
    await ctx.audit("BREACH_LOGGED", bid, oneOf(b.severity, SEVERITY, "medium"), user.id);
    return breachView(await db.get("SELECT * FROM breach_log WHERE id=$1", [bid]));
  }
  async function updateBreach(user, bid, b = {}) {
    const cur = await db.get("SELECT * FROM breach_log WHERE id=$1", [bid]); if (!cur) throw E.nf();
    const data = { ...(cur.data || {}) };
    if (b.categories !== undefined) data.categories = (Array.isArray(b.categories) ? b.categories : []).map(c => String(c).slice(0, 60)).slice(0, 30);
    if (b.measures !== undefined) data.measures = str(b.measures, 5000);
    if (b.note) data.notes = [...(data.notes || []), { at: now(), by: user.id, text: str(b.note, 1000) }].slice(-100);
    const v = {
      status: b.status !== undefined ? oneOf(b.status, BSTATUS, cur.status) : cur.status, severity: b.severity !== undefined ? oneOf(b.severity, SEVERITY, cur.severity) : cur.severity,
      contained_at: b.containedAt !== undefined ? isoOr(b.containedAt) : cur.contained_at, authority_notified_at: b.authorityNotifiedAt !== undefined ? isoOr(b.authorityNotifiedAt) : cur.authority_notified_at,
      users_notified_at: b.usersNotifiedAt !== undefined ? isoOr(b.usersNotifiedAt) : cur.users_notified_at, affected_count: b.affectedCount !== undefined ? (b.affectedCount === null || b.affectedCount === "" ? null : Math.max(0, Math.round(+b.affectedCount) || 0)) : cur.affected_count,
      description: b.description !== undefined ? str(b.description, 5000) : cur.description
    };
    if (v.status === "contained" && !v.contained_at) v.contained_at = now();
    await db.run("UPDATE breach_log SET status=$1, severity=$2, contained_at=$3, authority_notified_at=$4, users_notified_at=$5, affected_count=$6, description=$7, data=$8, updated_at=$9 WHERE id=$10",
      [v.status, v.severity, v.contained_at, v.authority_notified_at, v.users_notified_at, v.affected_count, v.description, data, now(), bid]);
    await ctx.audit("BREACH_UPDATED", bid, v.status, user.id);
    return breachView(await db.get("SELECT * FROM breach_log WHERE id=$1", [bid]));
  }
  /** in-app + push + email (security-class notification) to the listed accounts; records users_notified_at */
  async function notifyBreach(user, bid, b = {}) {
    const cur = await db.get("SELECT * FROM breach_log WHERE id=$1", [bid]); if (!cur) throw E.nf();
    const ids = [...new Set((Array.isArray(b.userIds) ? b.userIds : []).filter(x => typeof x === "string" && x.length < 60))].slice(0, 10000);
    if (!ids.length) throw E.bad("حدّد الحسابات المتأثرة");
    let n = 0; for (const uid of ids) { if ((await db.get("SELECT status FROM users WHERE id=$1", [uid]))?.status !== "active") continue; await notifyUser(uid, "security_breach", { ref: bid }); n++; }
    await db.run("UPDATE breach_log SET users_notified_at=COALESCE(users_notified_at,$1), updated_at=$1 WHERE id=$2", [now(), bid]);
    await ctx.audit("BREACH_USERS_NOTIFIED", bid, String(n), user.id);
    return { notified: n };
  }

  /* =====================================================================
   * 4. Retention
   * ===================================================================== */
  const enforceAllowed = () => env("RETENTION_ENFORCE", "0") === "1";
  async function rules() {
    const o = {}; for (const r of await db.all("SELECT * FROM retention_policies")) o[r.data_type] = { days: r.days, enabled: r.enabled };
    return L.retentionRules(o);
  }
  async function setRule(user, type, b = {}) {
    const def = L.RETENTION.find(r => r.type === type); if (!def) throw E.nf("نوع غير معروف");
    const days = b.days === undefined || b.days === null ? null : Math.round(+b.days);
    if (days !== null && (!Number.isFinite(days) || days < 1 || days > 3650)) throw E.bad("المدة بين 1 و3650 يوماً");
    const enabled = b.enabled === undefined || b.enabled === null ? null : b.enabled ? 1 : 0;
    await db.run("INSERT INTO retention_policies(data_type,days,enabled,updated_by,updated_at) VALUES($1,$2,$3,$4,$5) ON CONFLICT (data_type) DO UPDATE SET days=$2, enabled=$3, updated_by=$4, updated_at=$5", [type, days, enabled, user.id, now()]);
    await ctx.audit("RETENTION_RULE", type, `${days ?? "default"}d ${enabled ?? "default"}`, user.id);
    return (await rules()).find(r => r.type === type);
  }
  async function retentionRun({ enforce = false, by = "system" } = {}) {
    const mode = enforce && enforceAllowed() ? "enforce" : "dry-run", started = now(), results = [], T = await tables(), batch = Math.max(100, +env("RETENTION_BATCH", 5000) || 5000), maxBatches = 50;
    for (const r of await rules()) {
      const row = { type: r.type, label: r.label, table: r.t, days: r.days, enabled: r.enabled, action: r.action, matched: 0, affected: 0 };
      results.push(row);
      if (!r.enabled) { row.skipped = "disabled"; continue; }
      if (!T.has(r.t) || !(await columns(r.t)).has(r.at)) { row.skipped = "table/column missing"; continue; }
      const where = `${r.at} < $1${r.where ? ` AND ${r.where}` : ""}`, cut = L.cutoff(r.days);
      try {
        row.matched = Number((await db.get(`SELECT COUNT(*) n FROM ${r.t} WHERE ${where}`, [cut])).n);
        if (mode !== "enforce" || !row.matched) continue;
        if (r.action === "media") {
          if (env("RETENTION_MEDIA_BLOBS", "0") !== "1") { row.skipped = "media blobs need RETENTION_MEDIA_BLOBS=1"; continue; }
          for (const m of await db.all(`SELECT id, storage_key FROM media WHERE ${where} LIMIT ${batch}`, [cut])) { try { await ctx.storage.del(m.storage_key); } catch { } await db.run("UPDATE media SET status='purged' WHERE id=$1", [m.id]); row.affected++; }
        } else if (!r.key) row.affected = (await db.run(`DELETE FROM ${r.t} WHERE ${where}`, [cut])).changes;
        else for (let i = 0; i < maxBatches; i++) {
          const sub = `SELECT ${r.key} FROM ${r.t} WHERE ${where} LIMIT ${batch}`;
          const ch = (await db.run(r.action === "anonymise" ? `UPDATE ${r.t} SET ${r.set} WHERE ${r.key} IN (${sub})` : `DELETE FROM ${r.t} WHERE ${r.key} IN (${sub})`, [cut])).changes;
          row.affected += ch; if (ch < batch) break;
        }
      } catch (e) { row.error = e.message; }
    }
    const rid = id("rr");
    await db.run("INSERT INTO retention_runs(id,mode,data,by_user,started_at,finished_at) VALUES($1,$2,$3,$4,$5,$6)", [rid, mode, { results, enforceAllowed: enforceAllowed() }, by, started, now()]);
    if (mode === "enforce") await ctx.audit("RETENTION_ENFORCED", rid, results.filter(x => x.affected).map(x => `${x.type}:${x.affected}`).join(",") || "none", by);
    return { id: rid, mode, enforceAllowed: enforceAllowed(), results, exempt: L.RETENTION_EXEMPT };
  }

  /* =====================================================================
   * 8. Account decision log
   * ===================================================================== */
  const MOD_LABEL = { remove: "حذف محتوى في مجتمع", reject: "رفض منشور في مجتمع", warn: "إنذار من مشرفي مجتمع", mute: "كتم مؤقت في مجتمع", unmute: "إلغاء الكتم", ban: "حظر من مجتمع", unban: "إلغاء الحظر", automod_reject: "رفض آلي بقواعد المجتمع", automod_queue: "تحويل آلي للمراجعة", join_reject: "رفض طلب انضمام" };
  const DEC_LABEL = { REMOVED: "إزالة محتوى لمخالفته الإرشادات" };
  const extraSources = [];
  /** other phases can add entries: registerDecisionSource(async (uid) => [{ source, action, label, reason, at, ... }]) */
  const registerDecisionSource = (fn) => extraSources.push(fn);
  async function accountLog(user) {
    const T = await tables(), items = [];
    for (const d of await db.all("SELECT d.*, a.id AS appeal_id, a.status AS appeal_status, a.created_at AS appeal_at, a.resolved_at AS appeal_resolved_at FROM decisions d LEFT JOIN appeals a ON a.decision_id=d.id WHERE d.user_id=$1 ORDER BY d.created_at DESC LIMIT 300", [user.id])) {
      const p = await db.get("SELECT id, type, text, status FROM posts WHERE id=$1", [d.target]);
      items.push({ id: d.id, source: "platform", sourceLabel: "فريق مجتمع بلس", action: d.action, label: DEC_LABEL[d.action] || d.action, reason: d.reason, at: d.created_at, target: d.target,
        targetLabel: p ? (p.type === "post" ? "منشور" : "محتوى") : "تعليق", excerpt: p?.text ? String(p.text).slice(0, 120) : null, restored: !!+d.restored,
        appeal: d.appeal_id ? { id: d.appeal_id, status: d.appeal_status, at: d.appeal_at, resolvedAt: d.appeal_resolved_at } : null, canAppeal: !d.appeal_id && !+d.restored, appealHref: `/#/account-log?appeal=${d.id}` });
    }
    if (T.has("mod_actions")) {
      for (const m of await db.all(`SELECT m.*, c.name AS community_name FROM mod_actions m LEFT JOIN communities c ON c.id=m.community WHERE m.target_user=$1 AND m.action IN (${Object.keys(MOD_LABEL).map(k => `'${k}'`).join(",")}) ORDER BY m.created_at DESC LIMIT 300`, [user.id]))
        items.push({ id: m.id, source: "community", sourceLabel: m.actor === "system" ? `قواعد مجتمع ${m.community_name || ""}`.trim() : `مشرفو مجتمع ${m.community_name || ""}`.trim(), action: m.action, label: MOD_LABEL[m.action] || m.action, reason: m.reason, at: m.created_at, target: m.target_post || null,
          community: { id: m.community, name: m.community_name }, meta: m.meta || null, canAppeal: false, appealHref: `/#/c/${m.community}`, appealNote: "قرارات المجتمعات يراجعها مشرفو المجتمع نفسه؛ تواصل معهم من صفحة المجتمع." });
    }
    for (const a of await db.all("SELECT id, action, reason, at FROM audit_log WHERE target=$1 AND action IN ('USER_SUSPENDED','USER_ACTIVE') ORDER BY id DESC LIMIT 100", [user.id]))
      items.push({ id: "al" + a.id, source: "account", sourceLabel: "فريق مجتمع بلس", action: a.action, label: a.action === "USER_SUSPENDED" ? "إيقاف الحساب" : "إعادة تفعيل الحساب", reason: a.reason, at: a.at, canAppeal: false, appealNote: a.action === "USER_SUSPENDED" ? "للاعتراض على الإيقاف أرسل «طلباً بخصوص بياناتي» أو راسل الدعم." : null });
    for (const f of extraSources) { try { items.push(...(await f(user.id)) || []); } catch (e) { log.warn?.("decision source failed", { err: e.message }); } }
    items.sort((x, y) => String(y.at).localeCompare(String(x.at)));
    return { items, summary: { total: items.length, active: items.filter(i => i.source === "platform" && !i.restored).length, appealable: items.filter(i => i.canAppeal).length, openAppeals: items.filter(i => i.appeal?.status === "open").length } };
  }

  /* =====================================================================
   * 6–7. Readable public pages (server-rendered, no JS needed): /legal/:slug, /transparency[/:period]
   * ===================================================================== */
  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const fmtDate = (iso) => { try { return new Date(iso).toLocaleDateString("ar-SA-u-ca-gregory-nu-arab", { year: "numeric", month: "long", day: "numeric" }); } catch { return iso; } };
  const docs = async () => P.documents(process.env, await rules());
  function shell(title, inner, { desc = "" } = {}) {
    return `<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} · مجتمع بلس</title>${desc ? `<meta name="description" content="${esc(desc)}">` : ""}
<style>:root{--fg:#1d1b26;--mut:#5f5b73;--bg:#fbfaff;--card:#fff;--acc:#5b2bd6;--line:#e6e2f2;--ok:#1f7a4d}@media(prefers-color-scheme:dark){:root{--fg:#efedf7;--mut:#b3afc6;--bg:#121019;--card:#1b1824;--acc:#b9a2ff;--line:#2e2a3d;--ok:#7fd6a7}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:18px/1.9 "IBM Plex Sans Arabic","Noto Naskh Arabic",system-ui,sans-serif}a{color:var(--acc)}a:focus-visible,summary:focus-visible{outline:3px solid var(--acc);outline-offset:3px;border-radius:6px}
.skip{position:absolute;inset-inline-start:-999px}.skip:focus{inset-inline-start:12px;top:12px;background:var(--card);padding:8px 12px;z-index:9}
header.top{max-width:760px;margin:auto;padding:16px 20px;display:flex;gap:14px;flex-wrap:wrap;align-items:center;justify-content:space-between}header.top b{font-size:17px}nav a{margin-inline-start:14px;font-size:15px;font-weight:600;text-decoration:none}nav a[aria-current]{text-decoration:underline;text-underline-offset:6px}
main{max-width:760px;margin:auto;padding:4px 20px 80px}h1{font-size:1.9em;line-height:1.35;margin:.3em 0}.meta{color:var(--mut);font-size:15px}
.tldr{background:var(--card);border:1px solid var(--line);border-inline-start:5px solid var(--acc);border-radius:14px;padding:14px 20px;margin:18px 0 26px}.tldr h2{font-size:1.05em;margin:0 0 6px}.tldr ul{margin:0;padding-inline-start:1.2em}
.toc{font-size:15px;columns:2;column-gap:24px;margin:0 0 20px;padding-inline-start:1.2em}@media(max-width:560px){.toc{columns:1}}
section{border-top:1px solid var(--line);padding-top:6px}h2{font-size:1.3em;margin:1.1em 0 .3em}p{margin:0 0 .8em;max-width:68ch}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:14px 0}.stat{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:12px 14px}.stat b{display:block;font-size:1.6em;line-height:1.2}.stat span{color:var(--mut);font-size:14px}
table{border-collapse:collapse;width:100%;font-size:16px;margin:8px 0 16px}th,td{border-bottom:1px solid var(--line);padding:7px 8px;text-align:start}th{color:var(--mut);font-weight:600}
footer{max-width:760px;margin:auto;padding:20px;color:var(--mut);font-size:14px}</style></head>
<body><a class="skip" href="#main">تخطَّ إلى المحتوى</a><header class="top"><b>مجتمع بلس</b><nav aria-label="السياسات"><a href="/legal/terms">الشروط</a><a href="/legal/privacy">الخصوصية</a><a href="/legal/retention">الاحتفاظ</a><a href="/transparency">الشفافية</a><a href="/">التطبيق</a></nav></header>
<main id="main">${inner}</main><footer>نصوص مكتوبة بلغة واضحة. إن تعارض ملخص مع التفاصيل فالتفاصيل هي المرجع.</footer></body></html>`;
  }
  const docHtml = (d) => shell(d.title, `<h1>${esc(d.title)}</h1><p class="meta">الإصدار ${esc(d.version)} · سارية من ${esc(fmtDate(d.effective))}</p>
<div class="tldr" role="note"><h2>باختصار</h2><ul>${d.summary.map(s => `<li>${esc(s)}</li>`).join("")}</ul></div>
<nav aria-label="المحتويات"><ol class="toc">${d.sections.map(s => `<li><a href="#${esc(s.id)}">${esc(s.heading)}</a></li>`).join("")}</ol></nav>
${d.sections.map(s => `<section id="${esc(s.id)}" aria-labelledby="h-${esc(s.id)}"><h2 id="h-${esc(s.id)}">${esc(s.heading)}</h2>${s.body.map(p => `<p>${esc(p)}</p>`).join("")}</section>`).join("")}`, { desc: d.summary[0] });
  const num = (v) => (typeof v === "number" ? v.toLocaleString("ar-SA-u-nu-arab") : esc(v));
  const table = (obj, labels = {}) => { const e = Object.entries(obj || {}); return e.length ? `<table><thead><tr><th scope="col">النوع</th><th scope="col">العدد</th></tr></thead><tbody>${e.map(([k, v]) => `<tr><td>${esc(labels[k] || k)}</td><td>${num(v)}</td></tr>`).join("")}</tbody></table>` : `<p class="meta">لا شيء في هذه الفترة.</p>`; };
  const KL = { ...L.KIND_LABEL, REMOVED: "إزالة محتوى", ...MOD_LABEL, dismiss: "رفض بلاغ" };
  function transparencyHtml(t) {
    const stat = (v, l) => `<div class="stat"><b>${v === null || v === undefined ? "—" : num(v)}</b><span>${esc(l)}</span></div>`;
    return shell(`تقرير الشفافية · ${t.label}`, `<p><a href="/transparency">→ كل التقارير</a></p><h1>تقرير الشفافية: ${esc(t.label)}</h1><p class="meta">من ${esc(fmtDate(t.startsAt))} إلى ${esc(fmtDate(new Date(Date.parse(t.endsAt) - 1).toISOString()))} · أُعدّ ${esc(fmtDate(t.generatedAt))}</p>
<div class="grid">${stat(t.reports.received, "بلاغ وصلنا")}${stat(t.reports.actioned, "بلاغ اتُّخذ فيه إجراء")}${stat(t.reports.dismissed, "بلاغ بلا مخالفة")}${stat(t.reports.medianHoursToDecision, "ساعة (الوسيط) حتى القرار")}</div>
<section><h2>البلاغات حسب النوع</h2>${table(t.reports.byKind, KL)}</section>
<section><h2>قرارات الإشراف</h2><div class="grid">${stat(t.decisions.total, "قرار")}${stat(t.decisions.reversedOnAppeal, "قرار أُلغي بعد استئناف")}</div>${table(t.decisions.byAction, KL)}</section>
<section><h2>الاستئنافات</h2><div class="grid">${stat(t.appeals.received, "استئناف وصلنا")}${stat(t.appeals.accepted, "قُبل")}${stat(t.appeals.rejected, "رُفض")}${stat(t.appeals.medianHoursToDecision, "ساعة (الوسيط) حتى البتّ")}</div></section>
<section><h2>إشراف المجتمعات</h2><div class="grid">${stat(t.communityModeration.total, "إجراء من المشرفين")}${stat(t.communityModeration.automated, "منها بقواعد آلية")}</div>${table(t.communityModeration.byAction, KL)}</section>
<section><h2>الحسابات وطلبات البيانات</h2><div class="grid">${stat(t.accounts.suspended, "حساب موقوف")}${stat(t.accounts.reinstated, "حساب أُعيد تفعيله")}${stat(t.dataRequests.export, "طلب نسخة بيانات")}${stat(t.dataRequests.delete, "طلب حذف حساب")}</div></section>
<section><h2>ملاحظات منهجية</h2>${t.notes.map(n => `<p>${esc(n)}</p>`).join("")}</section>`, { desc: `تقرير الشفافية لـ${t.label}` });
  }
  async function ssr(req, res, url) {
    const page = (status, html) => { res.writeHead(status, { ...SEC_HEADERS, "Content-Type": "text/html; charset=utf-8", "Cache-Control": "public, max-age=300" }); res.end(html); return true; };
    let m = /^\/legal\/([a-z-]{2,20})\/?$/.exec(url.pathname);
    if (m) { const d = (await docs()).find(x => x.slug === m[1]); return d ? page(200, docHtml(d)) : page(404, shell("غير موجود", "<h1>الصفحة غير موجودة</h1>")); }
    if (url.pathname === "/transparency" || url.pathname === "/transparency/") {
      const list = await listTransparency();
      return page(200, shell("تقارير الشفافية", `<h1>تقارير الشفافية</h1><p>ننشر كل شهر وكل ربع سنة أرقاماً مجمّعة عن البلاغات وقرارات الإشراف والاستئنافات وطلبات البيانات. لا تحتوي التقارير أي بيانات شخصية.</p>
${list.length ? `<table><thead><tr><th scope="col">الفترة</th><th scope="col">بلاغات</th><th scope="col">إجراءات</th><th scope="col">استئنافات</th></tr></thead><tbody>${list.map(r => `<tr><td><a href="/transparency/${esc(r.period)}">${esc(r.label)}</a></td><td>${num(r.reports)}</td><td>${num(r.actioned)}</td><td>${num(r.appeals)}</td></tr>`).join("")}</tbody></table>` : `<p class="meta">لم يُنشر أول تقرير بعد؛ يصدر تلقائياً بعد انتهاء أول شهر.</p>`}`));
    }
    m = /^\/transparency\/(\d{4}-(?:\d{2}|Q[1-4]))\/?$/.exec(url.pathname);
    if (m) { const row = await db.get("SELECT data FROM transparency_reports WHERE period=$1 AND published=1", [m[1]]); return row ? page(200, transparencyHtml(row.data)) : page(404, shell("غير موجود", `<h1>لا يوجد تقرير لهذه الفترة</h1><p><a href="/transparency">كل التقارير</a></p>`)); }
    return false;
  }

  /* =====================================================================
   * routes
   * ===================================================================== */
  R.get("/api/legal", async () => ({ policies: (await docs()).map(d => ({ slug: d.slug, title: d.title, version: d.version, effective: d.effective, summary: d.summary, href: `/legal/${d.slug}` })) }));
  R.get("/api/legal/:slug", async (req) => { const d = (await docs()).find(x => x.slug === req.params.slug); if (!d) throw E.nf(); return { policy: d }; });
  R.get("/api/privacy/register", async () => register());
  R.get("/api/transparency", async () => ({ reports: await listTransparency() }));
  R.get("/api/transparency/:period", async (req) => ({ report: await getTransparency(req.params.period) }));

  R.get("/api/me/reports", A(async (req) => myReports(req.user)));
  R.get("/api/me/reports/:id", A(async (req) => { const r = await db.get("SELECT * FROM reports WHERE id=$1 AND by_user=$2", [req.params.id, req.user.id]); if (!r) throw E.nf(); return { report: await reportView(r) }; }));
  R.get("/api/me/account-log", A(async (req) => accountLog(req.user)));

  R.get("/api/me/privacy", A(async (req) => {
    const reqs = (await db.all("SELECT * FROM dsr_requests WHERE user_id=$1 ORDER BY created_at DESC LIMIT 50", [req.user.id])).map(reqView);
    const terms = (await docs()).find(d => d.slug === "terms"), acc = await db.get("SELECT version, at FROM consents WHERE user_id=$1 AND purpose='terms' ORDER BY id DESC LIMIT 1", [req.user.id]);
    return { consents: Object.values(await consents(req.user.id)), requests: reqs, deletion: reqs.find(r => r.kind === "delete" && ["scheduled", "processing"].includes(r.status)) || null, graceDays: L.GRACE_DAYS(),
      terms: { version: terms.version, accepted: acc?.version || null, acceptedAt: acc?.at || null, upToDate: acc?.version === terms.version }, requestKinds: REQUEST_KINDS, deadlineDays: L.DSR_DAYS, hasPassword: !!req.user.password_hash };
  }));
  R.get("/api/me/privacy/export", A(exportData));
  R.post("/api/me/privacy/deletion", A(async (req) => scheduleDeletion(req.user, req.body)));
  R.del("/api/me/privacy/deletion", A(async (req) => cancelDeletion(req.user)));
  R.post("/api/me/privacy/requests", A(async (req) => fileRequest(req.user, req.body)));
  R.get("/api/me/consents", A(async (req) => ({ consents: Object.values(await consents(req.user.id)) })));
  R.put("/api/me/consents", A(async (req) => { const r = await setConsents(req.user, req.body); return { consents: Object.values(r.consents), changed: r.changed }; }));

  R.get("/api/admin/compliance", admin(async () => {
    const reqs = await db.all("SELECT d.*, u.handle FROM dsr_requests d LEFT JOIN users u ON u.id=d.user_id WHERE d.status IN ('received','extended','scheduled','processing') ORDER BY d.due_at LIMIT 200");
    const lastRun = await db.get("SELECT * FROM retention_runs ORDER BY started_at DESC LIMIT 1");
    return {
      requests: reqs.map(r => ({ ...reqView(r), handle: r.handle, user: r.user_id, deadline: L.deadlineState(r.due_at, null, L.DSR_DAYS * L.DAY) })),
      breaches: (await db.all("SELECT * FROM breach_log ORDER BY detected_at DESC LIMIT 100")).map(breachView),
      retention: { rules: await rules(), exempt: L.RETENTION_EXEMPT, enforceAllowed: enforceAllowed(), mediaBlobsAllowed: env("RETENTION_MEDIA_BLOBS", "0") === "1", lastRun: lastRun ? { id: lastRun.id, mode: lastRun.mode, at: lastRun.started_at, results: lastRun.data?.results || [] } : null },
      transparency: await listTransparency(), register: register()
    };
  }));
  R.post("/api/admin/compliance/requests/:id", admin(async (req) => answerRequest(req.user, req.params.id, req.body)));
  R.post("/api/admin/transparency/generate", admin(async (req) => { const p = str(req.body.period, 10, { required: true }); return generateTransparency(p, req.user.id, { force: true }); }));
  R.get("/api/admin/retention/preview", admin(async (req) => retentionRun({ enforce: false, by: req.user.id })));
  R.post("/api/admin/retention/run", admin(async (req) => { if (req.body.enforce && !enforceAllowed()) throw E.off("التنفيذ الفعلي معطّل؛ يلزم ضبط RETENTION_ENFORCE=1 في بيئة التشغيل"); return retentionRun({ enforce: !!req.body.enforce, by: req.user.id }); }));
  R.put("/api/admin/retention/:type", admin(async (req) => ({ rule: await setRule(req.user, req.params.type, req.body) })));
  R.get("/api/admin/breaches", admin(async () => ({ breaches: (await db.all("SELECT * FROM breach_log ORDER BY detected_at DESC LIMIT 200")).map(breachView) })));
  R.post("/api/admin/breaches", admin(async (req) => ({ breach: await createBreach(req.user, req.body) })));
  R.patch("/api/admin/breaches/:id", admin(async (req) => ({ breach: await updateBreach(req.user, req.params.id, req.body) })));
  R.post("/api/admin/breaches/:id/notify", admin(async (req) => notifyBreach(req.user, req.params.id, req.body)));

  /* ---------- scheduled jobs (leased: one instance runs each) ---------- */
  if (env("COMPLIANCE_JOBS", "1") !== "0" && ctx.scheduler) {
    ctx.scheduler.every("compliance.reportSync", 120e3, () => syncReportUpdates());
    ctx.scheduler.every("compliance.deletions", 10 * 60e3, () => processDueDeletions());
    ctx.scheduler.every("compliance.transparency", 6 * 3600e3, () => transparencyJob());
    ctx.scheduler.every("compliance.retention", 24 * 3600e3, () => retentionRun({ enforce: enforceAllowed(), by: "system" }));
  }

  return { ssr, hasConsent, consents, buildTransparency, generateTransparency, transparencyJob, syncReportUpdates, processDueDeletions, eraseUser, retentionRun, accountLog, myReports, registerDecisionSource, register };
};
